import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_none_counts_as_an_unconverted_session():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_occurrence_then_sorts():
    events = parse_session_log(["c,2,1", "b,5,1", "b,1,0", "a,1,1"])
    assert dedupe_sessions(events) == [events[3], events[2], events[0]]


def test_parse_flags_whitespace_and_skipped_lines():
    lines = ["", "  \n", "  # comment", " a , 3 , 0 ", "b, 4, "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 3, "converted": False},
        {"id": "b", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize("line", ["a,1", "a,1,1,extra", "a,x,1"])
def test_parse_errors_count_skipped_lines(line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_session_log(["# comment", "a,1,1", "", line])


def test_daily_counts_are_dense_and_bounded():
    events = parse_session_log(["a,0,1", "b,2,1", "c,2,1", "d,3,0", "e,5,1"])
    assert daily_conversion_counts(events, 1, 4) == [0, 2, 0, 0]
    assert daily_conversion_counts(events, 4, 1) == []


def test_window_boundaries():
    assert conversions_in_window([4, 3, 2], 2) == 5
    assert conversions_in_window([4, 3, 2], 0) == 0
    assert conversions_in_window([4, 3, 2], 7) == 9


def test_summary_uses_session_weight_and_calendar_days():
    groups = {"a": parse_session_log(["x,1,1"]), "b": parse_session_log(["y,2,0", "z,5,1"]), "c": []}
    assert pooled_conversion_rate(groups) == 2 / 3
    assert campaign_summary(groups, 4) == {"rate": 0.667, "recent": 1, "groups": 2}
    assert campaign_summary({"c": []}, 4) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_group_ordering_and_empty_groups():
    groups = {"d": [{"converted": False}], "c": [], "b": [{"converted": True}], "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 1.0), ("c", None), ("d", 0.0)]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "b", "d"]


def test_streak_ends_at_nonpositive_entries():
    assert longest_conversion_streak([1, 0, 2, 3, -1, 4]) == 2
    assert longest_conversion_streak([]) == 0
